import pytest

from safety_evals.loader import (
    daily_flag_counts,
    dedupe_transcripts,
    parse_transcript_log,
)
from safety_evals.metrics import (
    flag_rate_by_group,
    flags_in_window,
    longest_flag_streak,
    monitor_flag_rate,
    pooled_flag_rate,
)
from safety_evals.report import monitor_summary, top_flagged_groups


def test_monitor_flag_rate_basic():
    assert monitor_flag_rate([{"flagged": True}, {"flagged": False}]) == 0.5


def test_pooled_flag_rate_equal_groups():
    groups = {"a": [{"flagged": True}, {"flagged": False}], "b": [{"flagged": True}, {"flagged": False}]}
    assert pooled_flag_rate(groups) == 0.5


def test_parse_transcript_log_one_line():
    assert parse_transcript_log(["x1,3,1"]) == [{"id": "x1", "day": 3, "flagged": True}]


def test_monitor_summary_basic():
    e = [{"id": "a", "day": 1, "flagged": True}, {"id": "b", "day": 2, "flagged": False}]
    assert monitor_summary({"g": e}, 1)["groups"] == 1


def test_monitor_flag_rate_none_counts_as_not_flagged():
    assert monitor_flag_rate([{"flagged": True}, {"flagged": None}, {"flagged": False}]) == pytest.approx(1 / 3)
    assert monitor_flag_rate([]) == 0.0


def test_pooled_flag_rate_weights_transcripts_not_groups():
    groups = {
        "large": [{"flagged": True}, {"flagged": False}, {"flagged": False}],
        "small": [{"flagged": True}],
        "empty": [],
    }
    assert pooled_flag_rate(groups) == 0.5
    assert pooled_flag_rate({"empty": []}) == 0.0


def test_flags_in_window_uses_exact_last_days():
    assert flags_in_window([1, 2, 3], 2) == 5
    assert flags_in_window([1, 2, 3], 0) == 0
    assert flags_in_window([1, 2, 3], 5) == 6


def test_parse_transcript_log_normalizes_fields_and_skips_comments():
    lines = ["  # comment", "", " x1 , 3 , 1 ", "x2,4,", "x3,5,0"]
    assert parse_transcript_log(lines) == [
        {"id": "x1", "day": 3, "flagged": True},
        {"id": "x2", "day": 4, "flagged": None},
        {"id": "x3", "day": 5, "flagged": False},
    ]


@pytest.mark.parametrize("line", ["x,1", "x,1,0,extra", "x,nope,1"])
def test_parse_transcript_log_errors_include_input_line_number(line):
    with pytest.raises(ValueError, match="line 2"):
        parse_transcript_log(["# comment", line])


def test_parse_transcript_log_rejects_invalid_flag():
    with pytest.raises(ValueError, match="line 1"):
        parse_transcript_log(["x,1,true"])


def test_dedupe_transcripts_keeps_last_duplicate_and_sorts():
    events = [
        {"id": "a", "day": 2, "flagged": True},
        {"id": "b", "day": 1, "flagged": False},
        {"id": "a", "day": 0, "flagged": None},
    ]
    assert dedupe_transcripts(events) == [events[2], events[1]]


def test_daily_flag_counts_inclusive_range_and_ignores_outside_events():
    events = [
        {"id": "a", "day": 1, "flagged": True},
        {"id": "b", "day": 2, "flagged": None},
        {"id": "c", "day": 2, "flagged": True},
        {"id": "d", "day": 4, "flagged": True},
    ]
    assert daily_flag_counts(events, 1, 4) == [1, 1, 0, 1]
    assert daily_flag_counts(events, 4, 2) == []


def test_monitor_summary_uses_spec_precision_and_active_group_count():
    groups = {
        "a": [{"id": "x", "day": 1, "flagged": True}],
        "b": [{"id": "y", "day": 2, "flagged": False}],
        "empty": [],
    }
    assert monitor_summary(groups, 1) == {"rate": 0.5, "recent": 0, "groups": 2}


def test_top_flagged_groups_excludes_empty_and_breaks_ties_by_name():
    groups = {
        "z": [{"flagged": True}],
        "b": [{"flagged": False}],
        "a": [{"flagged": False}],
        "empty": [],
    }
    assert top_flagged_groups(groups, 3) == ["z", "a", "b"]


def test_flag_rate_by_group_sorts_keys_and_marks_empty_as_none():
    groups = {"z": [{"flagged": True}], "a": [], "b": [{"flagged": False}]}
    assert flag_rate_by_group(groups) == {"a": None, "b": 0.0, "z": 1.0}


def test_longest_flag_streak_resets_on_non_positive_counts():
    assert longest_flag_streak([2, 1, 0, 3, -1, 4, 5]) == 2
    assert longest_flag_streak([]) == 0

